using System;using System.Configuration;using System.Data;using System.Web.UI;using System.Web.UI.WebControls;
namespace AQOONHUB_SMS.Modules.Communication{public partial class SmsEmail:CommunicationPageBase{bool EmailConfigured{get{return !string.IsNullOrWhiteSpace(ConfigurationManager.AppSettings["SmtpHost"])&&!string.IsNullOrWhiteSpace(ConfigurationManager.AppSettings["SmtpFromEmail"]);}}bool SmsConfigured{get{return false;}}protected void Page_Load(object s,EventArgs e){CommunicationAuthorization.Demand(this,CommunicationAuthorization.CanUseOutbound);if(!IsPostBack){LoadData();ShowProvider();ChannelUi();}}void LoadData(){ddlRecipient.DataSource=Repo.RecipientUsers(Role,UserId);ddlRecipient.DataTextField="FullName";ddlRecipient.DataValueField="UserID";ddlRecipient.DataBind();DataTable t=Repo.Templates();ddlTemplate.DataSource=t;ddlTemplate.DataTextField="Name";ddlTemplate.DataValueField="TemplateID";ddlTemplate.DataBind();ddlTemplate.Items.Insert(0,new ListItem("No template",""));gvTemplates.DataSource=t;gvTemplates.DataBind();gvCampaigns.DataSource=Repo.Campaigns(false);gvCampaigns.DataBind();gvScheduled.DataSource=Repo.Campaigns(true);gvScheduled.DataBind();}void ShowProvider(){string email=EmailConfigured?"Configured":"Provider Not Configured",sms=SmsConfigured?"Configured":"Provider Not Configured";litProviderSummary.Text="<div class='comm-list'><article><b>SMS</b><p class='comm-bad'>"+H(sms)+"</p></article><article><b>Email / SMTP</b><p class='"+(EmailConfigured?"comm-ok":"comm-bad")+"'>"+H(email)+"</p></article></div>";litProviderDetails.Text="<dl class='comm-detail'><dt>SMS</dt><dd>"+H(sms)+"</dd><dt>Email</dt><dd>"+H(email)+"</dd><dt>Scheduler</dt><dd>Not configured by this module</dd><dt>Secrets</dt><dd>Hidden</dd></dl>";}protected void Tab_Click(object s,EventArgs e){string tab=((LinkButton)s).CommandArgument;views.ActiveViewIndex=tab=="templates"?1:tab=="campaigns"?2:tab=="scheduled"?3:tab=="provider"?4:0;foreach(LinkButton x in new[]{tabCompose,tabTemplates,tabCampaigns,tabScheduled,tabProvider})x.CssClass="comm-tab";((LinkButton)s).CssClass="comm-tab active";}protected void Channel_Changed(object s,EventArgs e){ChannelUi();}void ChannelUi(){pnlSubject.Visible=ddlChannel.SelectedValue=="Email";bool configured=ddlChannel.SelectedValue=="Email"?EmailConfigured:SmsConfigured;btnSend.Enabled=configured||ddlTiming.SelectedValue=="Schedule Later";btnSend.ToolTip=configured?"":"Provider Not Configured. Save a draft or schedule definition instead.";}protected void Template_Changed(object s,EventArgs e){int id;if(!int.TryParse(ddlTemplate.SelectedValue,out id))return;DataRow[] r=Repo.Templates().Select("TemplateID="+id);if(r.Length==0)return;ddlChannel.SelectedValue=Convert.ToString(r[0]["Channel"]);txtSubject.Text=Convert.ToString(r[0]["SubjectTemplate"]);txtBody.Text=Convert.ToString(r[0]["BodyTemplate"]);ChannelUi();}void SaveCampaign(bool draft){try{string channel=ddlChannel.SelectedValue;ValidatePlaceholders(txtBody.Text);if(string.IsNullOrWhiteSpace(txtBody.Text))throw new InvalidOperationException("Message is required.");if(channel=="Email"&&string.IsNullOrWhiteSpace(txtSubject.Text))throw new InvalidOperationException("Email subject is required.");DateTime? schedule=ddlTiming.SelectedValue=="Schedule Later"?DateValue(txtSchedule.Text):null;if(schedule.HasValue&&schedule<=DateTime.Now)throw new InvalidOperationException("Schedule date must be in the future.");bool configured=channel=="Email"?EmailConfigured:SmsConfigured;if(!draft&&!schedule.HasValue&&!configured)throw new InvalidOperationException(channel+" Provider Not Configured. Save a draft or configure the provider in Settings.");if(!CommunicationAuthorization.CanTargetSchoolWide(Role)&&ddlRecipientType.SelectedValue.StartsWith("All "))throw new UnauthorizedAccessException("Your role cannot use unrestricted recipient groups.");long editId;long? campaignId=long.TryParse(hidCampaign.Value,out editId)?(long?)editId:null;long id=Repo.SaveCampaign(campaignId,channel,txtSubject.Text.Trim(),txtBody.Text.Trim(),ddlRecipientType.SelectedValue,ddlRecipient.SelectedValue,schedule,draft,UserId,Role);hidCampaign.Value="";Repo.Log(UserId,draft?"CAMPAIGN_CREATED":schedule.HasValue?"CAMPAIGN_SCHEDULED":channel.ToUpperInvariant()+"_SEND_ATTEMPTED","Campaign "+id+" saved; message body omitted",Ip);litMessage.Text="<div class='comm-note' role='status'>"+H(draft?"Draft saved.":schedule.HasValue?"Schedule definition saved as Pending Scheduler Configuration.":"Communication request saved as Pending; delivery is not claimed.")+"</div>";LoadData();}catch(Exception ex){litMessage.Text="<div class='comm-error' role='alert'>"+H(ex.GetBaseException().Message)+"</div>";}}protected void btnDraft_Click(object s,EventArgs e){SaveCampaign(true);}protected void btnSend_Click(object s,EventArgs e){SaveCampaign(false);}protected void btnPreview_Click(object s,EventArgs e){litMessage.Text="<div class='comm-note' role='status'><b>Preview:</b> "+H(txtSubject.Text)+"<br/>"+H(txtBody.Text).Replace("\r\n","<br/>")+"</div>";}protected void btnTemplateSave_Click(object s,EventArgs e){CommunicationAuthorization.Demand(this,CommunicationAuthorization.CanManageTemplates);try{if(string.IsNullOrWhiteSpace(txtTemplateName.Text)||string.IsNullOrWhiteSpace(txtTemplateBody.Text))throw new InvalidOperationException("Template name and body are required.");ValidatePlaceholders(txtTemplateSubject.Text+" "+txtTemplateBody.Text);int id=Repo.SaveTemplate(txtTemplateName.Text.Trim(),templateChannel.SelectedValue,txtCategory.Text.Trim(),txtTemplateSubject.Text.Trim(),txtTemplateBody.Text.Trim(),UserId);Repo.Log(UserId,"TEMPLATE_CREATED","Communication template "+id+" created",Ip);litMessage.Text="<div class='comm-note' role='status'>Template created.</div>";LoadData();}catch(Exception ex){litMessage.Text="<div class='comm-error' role='alert'>"+H(ex.GetBaseException().Message)+"</div>";}}protected void gvTemplates_RowCommand(object sender,GridViewCommandEventArgs e){CommunicationAuthorization.Demand(this,CommunicationAuthorization.CanManageTemplates);int id;if(!int.TryParse(Convert.ToString(e.CommandArgument),out id))return;if(e.CommandName=="ToggleTemplate"){Repo.X("UPDATE dbo.CommunicationTemplates SET IsActive=CASE WHEN IsActive=1 THEN 0 ELSE 1 END,UpdatedAt=SYSDATETIME() WHERE TemplateID=@id",new System.Data.SqlClient.SqlParameter("@id",id));Repo.Log(UserId,"TEMPLATE_UPDATED","Communication template "+id+" activation changed",Ip);}else if(e.CommandName=="DeleteTemplate"){int n=Repo.X("DELETE dbo.CommunicationTemplates WHERE TemplateID=@id AND IsActive=0",new System.Data.SqlClient.SqlParameter("@id",id));if(n==0){litMessage.Text="<div class='comm-error' role='alert'>Deactivate the template before deleting it.</div>";return;}}LoadData();}
protected void gvCampaigns_RowCommand(object sender,GridViewCommandEventArgs e){long id;if(!long.TryParse(Convert.ToString(e.CommandArgument),out id))return;if(e.CommandName=="EditCampaign"){DataRow c=Repo.EditableCampaign(id,UserId,Role);if(c==null){litMessage.Text="<div class='comm-error' role='alert'>Campaign cannot be edited.</div>";return;}hidCampaign.Value=id.ToString();ddlChannel.SelectedValue=Convert.ToString(c["Channel"]);txtSubject.Text=Convert.ToString(c["Subject"]);txtBody.Text=Convert.ToString(c["MessageBody"]);var audience=ddlRecipientType.Items.FindByValue(Convert.ToString(c["AudienceType"]));if(audience!=null)ddlRecipientType.SelectedValue=audience.Value;var recipient=ddlRecipient.Items.FindByValue(Convert.ToString(c["AudienceValue"]));if(recipient!=null)ddlRecipient.SelectedValue=recipient.Value;if(c["ScheduleAt"]!=DBNull.Value){ddlTiming.SelectedValue="Schedule Later";txtSchedule.Text=Convert.ToDateTime(c["ScheduleAt"]).ToString("yyyy-MM-ddTHH:mm");}else{ddlTiming.SelectedValue="Send Now";txtSchedule.Text="";}views.ActiveViewIndex=0;foreach(LinkButton x in new[]{tabCompose,tabTemplates,tabCampaigns,tabScheduled,tabProvider})x.CssClass="comm-tab";tabCompose.CssClass="comm-tab active";ChannelUi();litMessage.Text="<div class='comm-note' role='status'>Editing campaign "+id+". Save Draft or Send or Schedule to apply changes.</div>";return;}else if(e.CommandName=="CancelCampaign"){Repo.X("UPDATE dbo.CommunicationCampaigns SET Status='Cancelled',UpdatedAt=SYSDATETIME() WHERE CampaignID=@id AND Status IN('Pending','Pending Scheduler Configuration')",new System.Data.SqlClient.SqlParameter("@id",id));Repo.Log(UserId,"CAMPAIGN_CANCELLED","Campaign "+id+" cancelled",Ip);}else if(e.CommandName=="DeleteCampaign"){int n=Repo.X("DELETE dbo.CommunicationCampaigns WHERE CampaignID=@id AND Status='Draft'",new System.Data.SqlClient.SqlParameter("@id",id));if(n==0){litMessage.Text="<div class='comm-error' role='alert'>Only draft campaigns can be deleted.</div>";return;}}else if(e.CommandName=="DuplicateCampaign"){Repo.X("INSERT dbo.CommunicationCampaigns(Channel,Subject,MessageBody,AudienceType,AudienceValue,RecipientCount,Status,CreatedByUserID) SELECT Channel,Subject,MessageBody,AudienceType,AudienceValue,0,'Draft',@u FROM dbo.CommunicationCampaigns WHERE CampaignID=@id",new System.Data.SqlClient.SqlParameter("@u",UserId),new System.Data.SqlClient.SqlParameter("@id",id));Repo.Log(UserId,"CAMPAIGN_CREATED","Campaign duplicated from "+id+" as draft",Ip);}else{DataTable d=Repo.Q("SELECT TOP 1 CampaignID,Channel,Subject,AudienceType,RecipientCount,ScheduleAt,Status,CreatedAt FROM dbo.CommunicationCampaigns WHERE CampaignID=@id",new System.Data.SqlClient.SqlParameter("@id",id));if(d.Rows.Count>0){DataRow r=d.Rows[0];litMessage.Text="<div class='comm-note' role='status'><b>Campaign "+H(r["CampaignID"])+"</b> · "+H(r["Channel"])+" · "+H(r["AudienceType"])+" · "+H(r["Status"])+" · "+H(r["ScheduleAt"])+"</div>";return;}}LoadData();}}}
